/**
 * Enrich power values from health data
 *
 * Depending on device and version, power is reported per channel
 * (Gen2+: "switch:0".apower, "pm1:0".apower, "em:0".total_act_power,
 * "em1:0".act_power) or in lists (Gen1: meters[].power, emeters[].power).
 *
 * This function searches each device recursively and writes powerW
 * (sum of all channels), plus voltage, current, energy and output state
 * when available. Baselines, history and observations are skipped.
 *
 * If nothing is found, powerW stays untouched (never an artificial 0).
 *
 * Output 1: -> Update Shelly model
 * Output 2: diagnostics – first device without a power value
 */

// Per-channel instantaneous power
const POWER_KEYS = ["apower", "act_power", "power", "powerW", "activePowerW", "activePower"];
// Total power fields (take precedence to avoid double counting)
const TOTAL_KEYS = ["total_act_power", "totalActivePower", "totalPowerW"];
// Sections that do not contain live values
const SKIP = /^(baseline|baselines|history|observations|findings|peer|peers|stats|statistics|median|mad|threshold|thresholds|limits|settings|config|policy|policies|cards|summary|previous|aggregate|buckets)$/i;

function num(v) {
    if (v && typeof v === "object" && "value" in v) v = v.value;
    if (v === null || v === undefined || v === "" || typeof v === "boolean") return null;
    const n = Number(v);
    return Number.isFinite(n) ? n : null;
}

function scan(obj, depth, found) {
    if (!obj || typeof obj !== "object" || depth > 6) return;

    for (const [key, val] of Object.entries(obj)) {

        if (SKIP.test(key)) continue;

        if (TOTAL_KEYS.includes(key) && num(val) !== null) found.total.push(num(val));
        else if (POWER_KEYS.includes(key) && num(val) !== null) found.power.push(num(val));
        else if ((key === "voltage" || key === "voltageV") && num(val) !== null) found.voltage.push(num(val));
        else if ((key === "current" || key === "currentA") && num(val) !== null) found.current.push(num(val));
        else if (key === "aenergy" && val && num(val.total) !== null) found.energy.push(num(val.total));
        else if ((key === "output" || key === "ison") && typeof val === "boolean") found.output.push(val);
        else if (val && typeof val === "object") scan(val, depth + 1, found);
    }
}

function enrich(dev) {
    if (!dev || typeof dev !== "object") return false;

    const found = { power: [], total: [], voltage: [], current: [], energy: [], output: [] };
    scan(dev, 0, found);

    let power = null;
    if (found.total.length) power = found.total[0];
    else if (found.power.length) power = found.power.reduce((a, b) => a + b, 0);

    if (power === null) return false;

    dev.powerW = Math.round(power * 10) / 10;
    if (dev.voltage == null && found.voltage.length) dev.voltage = found.voltage[0];
    if (dev.current == null && found.current.length) dev.current = found.current.reduce((a, b) => a + b, 0);
    if (dev.energyWh == null && found.energy.length) dev.energyWh = found.energy.reduce((a, b) => a + b, 0);
    if (dev.output == null && found.output.length) dev.output = found.output.some(Boolean);
    return true;
}

const p = msg.payload || {};
const container = p.devices || (p.health && p.health.devices) || p.results || null;
const list = Array.isArray(container) ? container
    : container && typeof container === "object" ? Object.values(container) : [];

let withPower = 0;
for (const dev of list) if (enrich(dev)) withPower++;

const sample = list.find(d => d && d.powerW == null);

node.status({
    fill: withPower ? "green" : "yellow",
    shape: "dot",
    text: `${withPower}/${list.length} devices with power`
});

return [msg, sample ? { payload: sample, topic: "Device without power value" } : null];

/**
 * Update Shelly model
 *
 * Receives the outputs of the shelly-admin nodes and maintains a single
 * device model for the dashboard.
 *
 * msg.source (set by the change nodes):
 *   "inventory"  Discovery output 1
 *   "events"     Discovery output 2
 *   "health"     Monitor output 1 (incl. observations)
 *   "alerts"     Monitor output 2
 *   "maint"      Maintenance output 1 (result)
 *   "progress"   Maintenance output 2 (per-device progress)
 *   "errors"     Output 3 of all nodes
 *
 * Fields are read defensively from several possible paths.
 * Missing metrics stay null and are never turned into 0.
 */

const STORE = "file";
const HISTORY_STEP_MS = 15 * 60 * 1000;   // one history point per 15 min
const HISTORY_MAX = 96;                   // 24 h
const MAX_ALERT_LOG = 200;

// --------------------------------------------------
// Context with fallback to the default store
// --------------------------------------------------

function load(key, fallback) {
    try {
        const v = flow.get(key, STORE);
        return v === undefined ? fallback : v;
    } catch (e) {
        const v = flow.get(key);
        return v === undefined ? fallback : v;
    }
}

function save(key, value) {
    try {
        flow.set(key, value, STORE);
    } catch (e) {
        flow.set(key, value);
    }
}

// --------------------------------------------------
// Helpers
// --------------------------------------------------

// Read the first non-empty value from several paths ("a.b.c")
function pick(obj, paths) {
    for (const path of paths) {
        let cur = obj;
        for (const part of path.split(".")) {
            if (cur === null || cur === undefined) {
                break;
            }
            cur = cur[part];
        }
        if (cur !== undefined && cur !== null && cur !== "") {
            return cur;
        }
    }
    return null;
}

function num(value) {
    if (value === null || value === undefined || value === "" || typeof value === "boolean") {
        return null;
    }
    if (typeof value === "object") {
        return num(value.value ?? value.last ?? value.current ?? null);
    }
    const n = Number(value);
    return Number.isFinite(n) ? n : null;
}

function bool(value) {
    if (value === true || value === false) {
        return value;
    }
    if (["online", "ok", "reachable", "found"].includes(value)) {
        return true;
    }
    if (["offline", "unreachable", "error", "not-found"].includes(value)) {
        return false;
    }
    return null;
}

function str(value) {
    if (value === null || value === undefined) {
        return null;
    }
    if (typeof value === "object") {
        return str(value.version ?? value.name ?? value.id ?? null);
    }
    const s = String(value).trim();
    return s ? s : null;
}

// Extract a device list from any payload shape
function extractDevices(p) {

    if (!p || typeof p !== "object") {
        return [];
    }

    const candidates = [
        p.devices, p.inventory && p.inventory.devices, p.inventory,
        p.health && p.health.devices, p.health, p.results, p.deviceResults,
        p.items, p.device ? [p.device] : null
    ];

    for (let i = 0; i < candidates.length; i++) {

        const c = candidates[i];

        if (Array.isArray(c) && c.length && typeof c[0] === "object") {
            return c;
        }

        if (c && typeof c === "object" && !Array.isArray(c)) {

            // p.devices as object: key = device ID, take all entries.
            // Other candidates only if the entries look like devices.
            const strict = i !== 0;

            const values = Object.entries(c)
                .filter(([, v]) => v && typeof v === "object" && !Array.isArray(v)
                    && (!strict || v.ip || v.address || v.model || v.id || v.deviceId || v.mac))
                .map(([k, v]) => ({ id: k, ...v }));

            if (values.length) {
                return values;
            }
        }
    }

    if (Array.isArray(p) && p.length && typeof p[0] === "object") {
        return p;
    }

    return [];
}

function extractObservations(p) {
    if (!p) {
        return [];
    }
    if (Array.isArray(p)) {
        return p.filter(o => o && typeof o === "object");
    }
    const list = p.observations || p.alerts || p.findings || p.items;
    if (Array.isArray(list)) {
        return list;
    }
    if (p.kind || p.severity || p.lifecycle) {
        return [p];
    }
    return [];
}

// --------------------------------------------------
// Device type
// --------------------------------------------------
//
// Order:
//   1. Profile ("cover" on Plus/Pro 2PM in cover mode)
//   2. Shelly model code – unambiguous
//        Gen2+: SN.. (Plus), SP.. (Pro), S3.. (Gen3), S4.. (Gen4);
//               the next two letters define the type:
//               SW switch · PM power meter · EM energy meter · PL plug
//               DM dimmer · DC RGBW · SN sensor · BL/BU light · SH/CV cover · IX/BT input
//        Gen1:  SH* prefixes
//   3. App name (e.g. "MiniPMG3", "MiniEMG4", "Mini1PMG3")
//   4. Free-text fallback
//
// "1PM"/"2PM" = switch WITH metering (relay),
// "PM"/"EM" without a preceding digit = pure meter.

const TYPE_BY_CODE = {
    SW: "relay", PM: "energy", EM: "energy", PL: "plug",
    DM: "dimmer", DC: "light", SN: "sensor",
    BL: "light", BU: "light", RG: "light", LD: "light",
    SH: "cover", CV: "cover", IX: "input", BT: "input"
};

const GEN1_CODES = [
    [/^SHSW/, "relay"],
    [/^SHPLG|^SHPL/, "plug"],
    [/^SHEM/, "energy"],
    [/^SHDM|^SHDIMT/, "dimmer"],
    [/^SHRGBW|^SHBLB|^SHVIN|^SHBDUO|^SHCB|^SHCL/, "light"],
    [/^SHHT|^SHDW|^SHWT|^SHMOS|^SHGS|^SHSM|^SHSEN/, "sensor"],
    [/^SHIX|^SHBTN/, "input"],
    [/^SHUNI/, "relay"]
];

function classify(d) {

    const profile = String(d.profile || "").toLowerCase();

    if (profile.includes("cover") || profile.includes("roller")) {
        return "cover";
    }

    for (const raw of [d.modelCode, d.model]) {

        const code = String(raw || "").toUpperCase().trim();

        if (!code) {
            continue;
        }

        // i4 / i4DC report as SNSN-0024X / SNSN-0D24X -> inputs
        if (/^S[NP34]SN-(00|0D)24/.test(code)) {
            return "input";
        }

        const gen2 = code.match(/^S(?:N|P|3|4)([A-Z]{2})-/);

        if (gen2 && TYPE_BY_CODE[gen2[1]]) {
            return TYPE_BY_CODE[gen2[1]];
        }

        for (const [re, cat] of GEN1_CODES) {
            if (re.test(code)) {
                return cat;
            }
        }
    }

    const app = String(d.app || "").toLowerCase().replace(/[\s_-]/g, "");

    if (app) {
        if (/cover/.test(app)) return "cover";
        if (/^(mini)?pm(mini)?(g\d)?$|pmmini|minipm/.test(app)) return "energy";
        if (/em(g\d)?$|^(pro)?3?em|miniem/.test(app)) return "energy";
        if (/plug/.test(app)) return "plug";
        if (/dimmer/.test(app)) return "dimmer";
        if (/rgbw|bulb|duo|light/.test(app)) return "light";
        if (/^i4|^i3/.test(app)) return "input";
        if (/ht$|^ht|flood|smoke|motion|door|window|blu/.test(app)) return "sensor";
        if (/\dpm|plus1|pro\d|mini1|1l|2l|uni|switch|relay/.test(app)) return "relay";
    }

    const text = [d.model, d.name].filter(Boolean).join(" ").toLowerCase();

    if (/(cover|roller|shutter)/.test(text)) return "cover";
    if (/\bplug\b/.test(text)) return "plug";
    if (/dimmer/.test(text)) return "dimmer";
    if (/(rgbw|bulb|duo|vintage)/.test(text)) return "light";
    if (/(\bpm ?mini\b|\bmini ?pm\b|\b3em\b|\bpro ?em\b|\bem\b|energy meter)/.test(text)) return "energy";
    if (/(h&t|\bht\b|door|window|flood|smoke|motion|gas|sensor)/.test(text)) return "sensor";
    if (/(\bi3\b|\bi4\b|button)/.test(text)) return "input";
    if (/(\d ?pm\b|\bplus 1\b|\bpro \d|\bmini\b|\b1l\b|\b2l\b|\buni\b|switch|relay)/.test(text)) return "relay";

    return "other";
}

// --------------------------------------------------
// Normalise one device
// --------------------------------------------------

function normalizeDevice(raw) {

    const d = {};

    d.id = str(pick(raw, ["id", "deviceId", "device.id", "key", "mac", "device.mac"]));
    d.name = str(pick(raw, ["name", "device.name", "deviceName", "settings.name", "info.name"]));
    d.ip = str(pick(raw, ["ip", "address", "host", "device.ip", "lastKnownIp", "network.ip", "wifi.sta_ip"]));
    d.hostname = str(pick(raw, ["hostname", "device.hostname", "info.id"]));
    d.mac = str(pick(raw, ["mac", "device.mac", "info.mac"]));
    d.model = str(pick(raw, ["modelName", "model", "device.model", "info.model", "type"]));
    d.modelCode = str(pick(raw, ["modelCode", "model_code", "device.modelCode", "info.model", "info.type", "type", "model"]));
    d.app = str(pick(raw, ["app", "device.app", "info.app"]));
    d.profile = str(pick(raw, ["profile", "device.profile", "info.profile", "application"]));
    d.gen = num(pick(raw, ["generation", "gen", "device.generation", "device.gen", "info.gen"]));
    d.deviceClass = str(pick(raw, ["deviceClass", "class", "settings.deviceClass", "effective.deviceClass.value"]));

    // Reachability
    d.online = bool(pick(raw, ["online", "reachable", "isOnline", "status.online", "health.reachable", "lastScan.status", "status"]));
    d.confirmedOffline = pick(raw, ["confirmedOffline", "offline.confirmed"]) === true;
    d.lastSeen = str(pick(raw, ["lastSeen", "lastSeenAt", "lastSuccessAt", "lastContactAt", "lastOkAt", "updatedAt", "checkedAt", "timestamp"]));
    d.lastError = str(pick(raw, ["lastError.message", "lastError.code", "error.message", "error.code"]));

    // Firmware
    d.fw = str(pick(raw, ["firmware.version", "firmware.current", "firmwareVersion", "fw", "fw_id", "version", "ver", "info.ver"]));
    d.fwStable = str(pick(raw, ["firmware.available.stable", "firmware.stable.version", "firmware.stable", "firmware.update.stable.version", "firmware.latest", "firmware.available", "availableFirmware"]));
    d.fwBeta = str(pick(raw, ["firmware.available.beta", "firmware.beta.version", "firmware.beta", "firmware.update.beta.version"]));

    // Only set when it can be determined; null never overwrites
    const updFlag = pick(raw, ["firmware.updateAvailable", "firmware.policyEligible", "updateAvailable", "firmware.eligible"]);

    if (updFlag === true || updFlag === false) {
        d.updateAvailable = updFlag;
    } else if (d.fw && d.fwStable) {
        d.updateAvailable = d.fwStable !== d.fw;
    } else {
        d.updateAvailable = null;
    }

    // Metrics (only when reported)
    d.temperature = num(pick(raw, ["temperatureC", "temperature", "temp", "metrics.temperatureC", "metrics.temperature", "measurements.temperature", "sys.temperature", "latest.temperatureC"]));
    d.rssi = num(pick(raw, ["rssi", "wifiRssi", "wifi.rssi", "metrics.rssi", "measurements.rssi", "latest.rssi"]));
    d.uptimeSec = num(pick(raw, ["uptimeSec", "uptime", "metrics.uptimeSec", "metrics.uptime", "sys.uptime", "latest.uptimeSec"]));
    d.uptimeBeforeReboot = num(pick(raw, ["uptimeBeforeRebootSec", "previousUptimeSec", "reboot.uptimeBeforeSec"]));
    d.lastReboot = str(pick(raw, ["lastRebootAt", "reboot.lastAt", "lastReboot.at"]));
    d.latencyMs = num(pick(raw, ["latencyMs", "responseTimeMs", "latency", "metrics.latencyMs", "metrics.responseTimeMs", "latest.latencyMs"]));
    d.ramFreePct = num(pick(raw, ["ramFreePercent", "freeRamPercent", "metrics.ramFreePercent", "metrics.ramFreePct", "resources.ramFreePercent"]));
    d.fsFreePct = num(pick(raw, ["fsFreePercent", "freeFsPercent", "metrics.fsFreePercent", "metrics.fsFreePct", "resources.fsFreePercent"]));
    d.powerW = num(pick(raw, ["powerW", "apower", "power", "metrics.powerW", "metrics.power", "electrical.powerW", "latest.powerW"]));
    d.voltage = num(pick(raw, ["voltage", "voltageV", "metrics.voltage", "electrical.voltage", "latest.voltage"]));
    d.current = num(pick(raw, ["current", "currentA", "metrics.current", "electrical.current", "latest.current"]));
    d.energyWh = num(pick(raw, ["energyWh", "energy", "aenergy.total", "metrics.energyWh", "electrical.energyWh", "latest.energyWh"]));

    const output = pick(raw, ["output", "relay.ison", "ison", "switch.output", "state.output"]);
    d.output = output === true || output === false ? output : null;

    return d;
}

// Merge new values (null never overwrites)
function merge(target, src) {
    for (const [k, v] of Object.entries(src)) {
        if (v !== null && v !== undefined) {
            target[k] = v;
        }
    }
    return target;
}

// --------------------------------------------------
// Load state
// --------------------------------------------------

const model = load("shellyDash", null) || { devices: {}, alerts: {}, alertLog: [], runs: {}, errors: [] };
const history = load("shellyDashHistory", {});
const now = Date.now();
const nowIso = new Date(now).toISOString();
const p = msg.payload;

// Find device by ID or IP, or create it
function upsert(d) {

    let key = d.id;

    if (!key && d.ip) {
        key = Object.keys(model.devices).find(k => model.devices[k].ip === d.ip) || null;
    }

    if (!key) {
        return null;
    }

    const existing = model.devices[key] || { id: key, firstSeen: nowIso };
    merge(existing, d);
    existing.id = key;
    existing.category = classify(existing);
    model.devices[key] = existing;
    return existing;
}

// Re-classify stored devices on every run
for (const dev of Object.values(model.devices)) {
    dev.category = classify(dev);
}

// --------------------------------------------------
// Per source
// --------------------------------------------------

const source = msg.source || "health";

if (source === "inventory" || source === "health" || source === "events") {

    for (const raw of extractDevices(p)) {

        const d = upsert(normalizeDevice(raw));

        if (!d) {
            continue;
        }

        if (source !== "events") {
            d.lastUpdate = nowIso;
        }

        // History (temperature, power, RSSI) on a 15-min grid
        if (source === "health" && (d.temperature !== null || d.powerW !== null || d.rssi !== null)) {

            const h = history[d.id] || [];
            const last = h[h.length - 1];
            const point = { t: now, temp: d.temperature ?? null, p: d.powerW ?? null, rssi: d.rssi ?? null };

            if (last && now - last.t < HISTORY_STEP_MS) {
                h[h.length - 1] = { ...point, t: last.t };
            } else {
                h.push(point);
            }

            history[d.id] = h.slice(-HISTORY_MAX);
        }
    }
}

// Observations (from health or alerts)
if (source === "health" || source === "alerts") {

    for (const o of extractObservations(source === "alerts" ? p : (p && p.observations))) {

        const devId = str(pick(o, ["device.id", "deviceId", "device"])) || "global";
        const kind = str(pick(o, ["kind", "category", "type", "code"])) || "notice";
        const key = str(pick(o, ["id", "observationId", "key"])) || `${devId}:${kind}`;
        const lifecycle = str(pick(o, ["lifecycle", "state", "transition"])) || "present";

        const entry = {
            key,
            deviceId: devId,
            deviceName: str(pick(o, ["device.name", "deviceName"])),
            ip: str(pick(o, ["device.ip", "ip"])),
            kind,
            severity: (str(pick(o, ["severity", "level"])) || "info").toLowerCase(),
            lifecycle,
            text: str(pick(o, ["summaryTextDe", "summaryText", "humanSummary", "title", "reasons.0", "message"])) || kind,
            textEn: str(pick(o, ["summaryText", "humanSummary", "title", "reasons.0", "message", "summaryTextDe"])) || kind,
            notify: o.notify === true,
            at: str(pick(o, ["at", "timestamp", "time", "updatedAt", "openedAt"])) || nowIso
        };

        if (lifecycle === "cleared" || lifecycle === "suppressed") {
            delete model.alerts[key];
        } else {
            model.alerts[key] = entry;
        }

        if (lifecycle !== "present") {
            model.alertLog.unshift(entry);
        }
    }

    model.alertLog = model.alertLog.slice(0, MAX_ALERT_LOG);
}

// Run status (lifecycle) of all nodes
const lifecycle = p && (p.lifecycle || (p.runId || p.state ? p : null));

if (lifecycle && typeof lifecycle === "object") {

    const nodeKey = {
        inventory: "discovery", events: "discovery",
        health: "monitor", alerts: "monitor",
        maint: "maintenance", progress: "maintenance"
    }[source];

    if (nodeKey) {
        model.runs[nodeKey] = {
            state: str(lifecycle.state) || model.runs[nodeKey]?.state || null,
            phase: str(lifecycle.phase),
            processed: num(lifecycle.processed),
            total: num(lifecycle.total),
            action: str(lifecycle.action || p.action),
            runId: str(lifecycle.runId),
            at: nowIso
        };
    }
}

// Maintenance: per-device result and progress
if (source === "maint" || source === "progress") {

    for (const r of extractDevices(p)) {

        const id = str(pick(r, ["id", "deviceId", "device.id"]));

        if (!id || !model.devices[id]) {
            continue;
        }

        const dev = model.devices[id];

        dev.maintenance = {
            status: str(pick(r, ["status", "result", "state"])),
            reason: str(pick(r, ["reason", "error.code", "error.message"])),
            at: nowIso
        };

        merge(dev, {
            fw: str(pick(r, ["firmware.version", "current", "currentVersion", "firmware.current"])),
            fwStable: str(pick(r, ["firmware.available.stable", "available.stable", "stable", "targetVersion", "firmware.stable"])),
            fwBeta: str(pick(r, ["firmware.available.beta", "available.beta", "beta", "firmware.beta"]))
        });

        const elig = pick(r, ["eligible", "policyEligible", "updateAvailable"]);

        if (elig === true || elig === false) {
            dev.updateAvailable = elig;
        }
    }
}

// Error outputs
if (source === "errors") {

    model.errors.unshift({
        at: nowIso,
        text: str(pick(p, ["messageDe", "message", "error.message", "code"])) || "Unbekannter Fehler",
        textEn: str(pick(p, ["message", "error.message", "code", "messageDe"])) || "Unknown error",
        deviceId: str(pick(p, ["device.id", "deviceId"]))
    });

    model.errors = model.errors.slice(0, 50);
}

model.updated = nowIso;

save("shellyDash", model);
save("shellyDashHistory", history);

node.status({
    fill: "green",
    shape: "dot",
    text: `${source} · ${Object.keys(model.devices).length} devices · ${Object.keys(model.alerts).length} alerts`
});

return { trigger: true };

/**
 * Build dashboard model (debounced)
 *
 * Combines devices, alerts, runs and history into ONE message for the
 * dashboard. Several changes within 500 ms result in a single message.
 */

const DEBOUNCE_MS = 500;
const STORE = "file";

function load(key, fallback) {
    try {
        const v = flow.get(key, STORE);
        return v === undefined ? fallback : v;
    } catch (e) {
        const v = flow.get(key);
        return v === undefined ? fallback : v;
    }
}

function build() {

    const model = load("shellyDash", null) || { devices: {}, alerts: {}, alertLog: [], runs: {}, errors: [] };
    const history = load("shellyDashHistory", {});
    const armedUntil = flow.get("shellyArmedUntil") || 0;
    const now = Date.now();

    // Count active alerts per device
    const alertsByDevice = {};

    for (const a of Object.values(model.alerts)) {
        const k = a.deviceId;
        alertsByDevice[k] = alertsByDevice[k] || { warning: 0, critical: 0, info: 0 };
        const sev = a.severity === "critical" ? "critical" : a.severity === "warning" ? "warning" : "info";
        alertsByDevice[k][sev] += 1;
    }

    const devices = Object.values(model.devices).map(d => {

        const a = alertsByDevice[d.id] || { warning: 0, critical: 0, info: 0 };

        let status = "unknown";

        if (d.confirmedOffline || d.online === false) {
            status = "offline";
        } else if (d.online === true) {
            status = a.critical ? "critical" : a.warning ? "warning" : "online";
        }

        // Data older than 15 min is considered stale
        const age = d.lastUpdate ? now - Date.parse(d.lastUpdate) : null;

        return {
            ...d,
            status,
            stale: age === null || age > 15 * 60 * 1000,
            alerts: a,
            history: history[d.id] || []
        };
    });

    const rank = { critical: 0, warning: 1, info: 2 };

    const alerts = Object.values(model.alerts)
        .sort((x, y) => (rank[x.severity] ?? 3) - (rank[y.severity] ?? 3) || String(y.at).localeCompare(String(x.at)));

    const online = devices.filter(d => d.status !== "offline" && d.status !== "unknown").length;

    node.status({
        fill: devices.some(d => d.status === "offline") ? "yellow" : "green",
        shape: "dot",
        text: `${online}/${devices.length} online · ${alerts.length} alerts`
    });

    return {
        payload: {
            updated: model.updated || new Date().toISOString(),
            devices,
            alerts,
            alertLog: (model.alertLog || []).slice(0, 50),
            runs: model.runs || {},
            errors: (model.errors || []).slice(0, 20),
            armed: armedUntil > now,
            armedUntil,
            lastCommand: flow.get("shellyLastCommand") || null
        }
    };
}

const timer = context.get("timer");

if (timer) {
    clearTimeout(timer);
}

context.set("timer", setTimeout(() => {
    context.set("timer", null);
    node.send(build());
}, DEBOUNCE_MS));

return null;

/**
 * Validate and route dashboard commands
 *
 * Input from the dashboard: msg.payload = { target, action, ... }
 *
 *   target "discovery"    action "scan"   mode "incremental" | "full"
 *   target "monitor"      action "poll"   devices (optional)
 *   target "maintenance"  action "check"  devices (optional)   – read-only
 *   target "maintenance"  action "dryrun" devices               – dry run
 *   target "maintenance"  action "update" devices               – REAL, only while unlocked
 *   target "maintenance"  action "reboot" devices               – REAL, only while unlocked
 *   target "device"       action "switch" id, channel, on, confirm
 *   target "device"       action "status" id (optional)
 *   target "ui"           action "arm"    value true|false
 *   target "ui"           action "forget" id
 *
 * Output 1: discovery   Output 2: monitor   Output 3: maintenance
 * Output 4: trigger for the dashboard model
 * Output 5: switch command (HTTP to the device)
 * Output 6: read switch state
 *
 * Switching: relays and plugs only, known channels only, online only.
 * Devices of class "critical"/"kritisch" require confirm:true
 * (second click in the dashboard).
 */

const ARM_MS = 10 * 60 * 1000;
const MAX_REAL_DEVICES = 5;
const SWITCHABLE = ["relay", "plug"];

const cmd = msg.payload || {};
const now = Date.now();
const out = [null, null, null, { trigger: true }, null, null];

function feedback(ok, de, en) {
    flow.set("shellyLastCommand", { ts: now, ok, de, en, text: de });
    node.status({ fill: ok ? "green" : "red", shape: "dot", text: en });
}

function deviceList(value) {
    if (!Array.isArray(value)) {
        return [];
    }
    return value.map(String).filter(Boolean).slice(0, 200);
}

function loadModel() {
    try {
        return flow.get("shellyDash", "file");
    } catch (e) {
        return flow.get("shellyDash");
    }
}

function genOf(d) {
    if (Number(d.gen) >= 1) {
        return Number(d.gen);
    }
    return /^SH/i.test(String(d.modelCode || d.model || "")) ? 1 : 2;
}

const devices = deviceList(cmd.devices);
const n = devices.length;

switch (`${cmd.target}:${cmd.action}`) {

    case "discovery:scan": {
        const mode = cmd.mode === "full" ? "full" : "incremental";
        out[0] = { action: "scan", mode };
        feedback(true,
            mode === "full" ? "Vollscan gestartet" : "Inventarprüfung gestartet",
            mode === "full" ? "Full scan started" : "Inventory check started");
        break;
    }

    case "monitor:poll": {
        out[1] = n ? { action: "poll", devices } : { action: "poll" };
        // Refresh switch states as well
        out[5] = n === 1 ? { deviceId: devices[0] } : {};
        feedback(true,
            n ? `Abfrage für ${n} Gerät(e)` : "Abfrage aller Geräte gestartet",
            n ? `Polling ${n} device(s)` : "Polling all devices");
        break;
    }

    case "maintenance:check": {
        out[2] = n ? { action: "check", devices } : { action: "check" };
        feedback(true, "Firmwareprüfung gestartet (nur lesend)", "Firmware check started (read-only)");
        break;
    }

    case "maintenance:dryrun": {
        if (!n) {
            feedback(false, "Probelauf: keine Geräte ausgewählt", "Dry run: no devices selected");
            break;
        }
        out[2] = { action: "update", devices, dryRun: true };
        feedback(true, `Update-Probelauf für ${n} Gerät(e)`, `Update dry run for ${n} device(s)`);
        break;
    }

    case "maintenance:update":
    case "maintenance:reboot": {

        const armed = (flow.get("shellyArmedUntil") || 0) > now;
        const de = cmd.action === "update" ? "Firmwareupdate" : "Neustart";
        const en = cmd.action === "update" ? "Firmware update" : "Reboot";

        if (!armed) {
            feedback(false, `${de} blockiert: Wartung ist nicht freigeschaltet`, `${en} blocked: maintenance is locked`);
            break;
        }
        if (!n) {
            feedback(false, `${de} blockiert: kein Gerät ausgewählt`, `${en} blocked: no device selected`);
            break;
        }
        if (n > MAX_REAL_DEVICES) {
            feedback(false, `${de} blockiert: max. ${MAX_REAL_DEVICES} Geräte pro Befehl`, `${en} blocked: max. ${MAX_REAL_DEVICES} devices per command`);
            break;
        }
        if (cmd.confirm !== true) {
            feedback(false, `${de} blockiert: keine Bestätigung`, `${en} blocked: not confirmed`);
            break;
        }

        out[2] = { action: cmd.action, devices, dryRun: false, confirm: true };
        feedback(true, `${de} gesendet: ${n} Gerät(e)`, `${en} sent: ${n} device(s)`);
        break;
    }

    // ----------------------------------------------
    // Switch a channel
    // ----------------------------------------------
    case "device:switch": {

        const model = loadModel();
        const dev = model && model.devices ? model.devices[String(cmd.id)] : null;

        if (!dev) {
            feedback(false, "Schalten: Gerät unbekannt", "Switch: unknown device");
            break;
        }

        const name = dev.name || dev.id;

        if (!SWITCHABLE.includes(dev.category)) {
            feedback(false, `${name}: Gerät ist nicht schaltbar`, `${name}: device is not switchable`);
            break;
        }
        if (!dev.ip) {
            feedback(false, `${name}: keine IP-Adresse bekannt`, `${name}: no IP address known`);
            break;
        }
        if (dev.confirmedOffline || dev.online === false) {
            feedback(false, `${name}: Gerät ist offline`, `${name}: device is offline`);
            break;
        }

        const channel = Math.round(Number(cmd.channel));
        const channels = Array.isArray(dev.channels) ? dev.channels : [];

        if (!channels.some(c => c.id === channel)) {
            feedback(false,
                `${name}: Kanal ${channel + 1} unbekannt (Schaltzustand noch nicht gelesen)`,
                `${name}: channel ${channel + 1} unknown (state not read yet)`);
            break;
        }

        const critical = /krit|crit/i.test(String(dev.deviceClass || ""));

        if (critical && cmd.confirm !== true) {
            feedback(false,
                `${name}: kritisches Gerät, zweite Bestätigung erforderlich`,
                `${name}: critical device, second confirmation required`);
            break;
        }

        const on = cmd.on === true;
        const gen = genOf(dev);

        out[4] = {
            kind: "switch",
            deviceId: dev.id,
            channel,
            on,
            gen,
            requestTimeout: 5000,
            url: gen >= 2
                ? `http://${dev.ip}/rpc/Switch.Set?id=${channel}&on=${on}`
                : `http://${dev.ip}/relay/${channel}?turn=${on ? "on" : "off"}`
        };

        // Feedback follows the device response
        node.status({ fill: "blue", shape: "dot", text: `${name} · channel ${channel + 1} → ${on ? "ON" : "OFF"}` });
        out[3] = null;
        break;
    }

    case "device:status": {
        out[5] = cmd.id ? { deviceId: String(cmd.id) } : {};
        out[3] = null;
        break;
    }

    case "ui:arm": {
        const on = cmd.value === true;
        flow.set("shellyArmedUntil", on ? now + ARM_MS : 0);
        feedback(true,
            on ? "Wartung für 10 Minuten freigeschaltet" : "Wartung gesperrt",
            on ? "Maintenance unlocked for 10 minutes" : "Maintenance locked");
        break;
    }

    case "ui:forget": {
        const model = loadModel();
        if (model && model.devices && model.devices[cmd.id]) {
            delete model.devices[cmd.id];
            try { flow.set("shellyDash", model, "file"); } catch (e) { flow.set("shellyDash", model); }
            feedback(true, "Gerät aus dem Dashboard entfernt (Inventar unverändert)", "Device removed from dashboard (inventory unchanged)");
        }
        break;
    }

    default:
        feedback(false, `Unbekannter Befehl ${cmd.target}:${cmd.action}`, `Unknown command ${cmd.target}:${cmd.action}`);
}

return out;

/**
 * Read switch state
 *
 * Reads the state of every channel of all relays and plugs directly
 * via the local Shelly API:
 *
 *   Gen2+  GET http://IP/rpc/Shelly.GetStatus   (switch:0 … switch:3)
 *          GET http://IP/rpc/Shelly.GetConfig   (channel names, every 6 h)
 *   Gen1   GET http://IP/status                 (relays[], meters[])
 *          GET http://IP/settings               (channel names, every 6 h)
 *
 * Input:
 *   - inject (every 30 s)              -> all switchable devices
 *   - msg.deviceId                     -> this device only (after switching)
 *
 * Output: one HTTP request per device and kind (through a rate limit).
 */

const STORE = "file";
const SWITCHABLE = ["relay", "plug"];
const CONFIG_MAX_AGE_MS = 6 * 3600 * 1000;
const TIMEOUT_MS = 4000;

function load(key, fallback) {
    try {
        const v = flow.get(key, STORE);
        return v === undefined ? fallback : v;
    } catch (e) {
        const v = flow.get(key);
        return v === undefined ? fallback : v;
    }
}

// Determine generation (Gen1 model codes start with "SH")
function genOf(d) {
    if (Number(d.gen) >= 1) {
        return Number(d.gen);
    }
    return /^SH/i.test(String(d.modelCode || d.model || "")) ? 1 : 2;
}

const model = load("shellyDash", null) || { devices: {} };
const only = msg.deviceId ? String(msg.deviceId) : null;
const now = Date.now();
const out = [];

for (const d of Object.values(model.devices || {})) {

    if (only && d.id !== only) {
        continue;
    }

    if (!SWITCHABLE.includes(d.category) || !d.ip) {
        continue;
    }

    // Offline devices only on targeted requests
    if (!only && (d.confirmedOffline || d.online === false)) {
        continue;
    }

    const gen = genOf(d);
    const base = { deviceId: d.id, gen, requestTimeout: TIMEOUT_MS };

    out.push({
        ...base,
        kind: "status",
        url: gen >= 2 ? `http://${d.ip}/rpc/Shelly.GetStatus` : `http://${d.ip}/status`
    });

    const namesAt = Date.parse(d.channelNamesAt || "");

    if (!Number.isFinite(namesAt) || now - namesAt > CONFIG_MAX_AGE_MS) {
        out.push({
            ...base,
            kind: "config",
            url: gen >= 2 ? `http://${d.ip}/rpc/Shelly.GetConfig` : `http://${d.ip}/settings`
        });
    }
}

node.status({
    fill: out.length ? "blue" : "grey",
    shape: "dot",
    text: `${out.length} requests${only ? " · " + only : ""}`
});

return [out];
